    $('caldavPreview').onclick=async()=>{if(!filePath||dirty||saving||importing)return;$('caldavStatus').textContent='Checking the configured calendar…';caldavPlan=null;caldavBusy(true);const controller=new AbortController(),path=filePath,base=revision;caldavController=controller;try{const result=await(await RoomShared.request('/api/workspace/caldav',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,base_revision:base,mode:'preview',allow_deletions:$('caldavDeletions').checked}),signal:controller.signal})).json();if(filePath!==path||revision!==base||dirty)throw new Error('The calendar changed. Save and preview again.');caldavPlan={token:result.plan_token,path,revision:base,allowDeletions:result.allow_deletions};caldavList(result.changes,result.unsupported);$('caldavStatus').textContent='Review the changes and conflicts below before syncing.';}catch(error){if(!controller.signal.aborted)$('caldavStatus').textContent=error.message;}finally{if(caldavController===controller)caldavController=null;caldavBusy(false);}};
